transforms.append:
/* Microfix 3.8.34: one baseline for every header dropdown/popover */
:root{--bc-header-menu-top:68px}
#projectPopover.popover,.profile-menu,.export-menu,.activity-panel,.collab-popover,.modules-popover,.update-popover{top:var(--bc-header-menu-top)!important}
.update-popover,.modules-popover{max-height:calc(100vh - 84px)!important}
@media(max-width:900px){:root{--bc-header-menu-top:64px}}
